{"script":"export default async function workflow(host) {
  const sweeps = await host.parallel([
    { input: "Map top-level repo layout for deep-dive onboarding. List key directories, tech stack (languages, frameworks, package managers), entry points, and README/docs. Read AGENTS.md plus .dev/DataIntegration/copilot-guidelines.md, .dev/fcm/copilot-guidelines.md, .dev/shared-guidelines.md as context. Make at most two tool batches, then report findings with file paths.", label: "layout-sweep" },
    { input: "Survey FCM area: directory structure, architecture, modular layers, key components and concerns separation, conventions from .dev/fcm/copilot-guidelines.md. Make at most two tool batches, report with file:line evidence.", label: "fcm-sweep" },
    { input: "Survey DataIntegration area: directory structure, architecture, key components, conventions from .dev/DataIntegration/copilot-guidelines.md. Make at most two tool batches, report with file:line evidence.", label: "di-sweep" },
    { input: "Survey shared conventions, build/test/lint setup: read .dev/shared-guidelines.md, Makefile/task files, CI configs, package metadata, hidden linter configs. Report exact build, test, and lint commands. Make at most two tool batches.", label: "config-sweep" },
    { input: "Survey tests and docs: tests/ dirs, test-file siblings, browser-test conventions (partner/section selector in bottom debug bar), docs. Report how to run relevant tests. Make at most two tool batches.", label: "tests-sweep" }
  ]);
  const critic = await host.agent({
    input: `Audit these deep-dive sweep results for gaps - unread area, unverified claim, missing architecture layer: ${sweeps.map((s) => s.ref).join(" ")}. Set followups to a JSON array of concrete next steps, [] if complete.`,
    schema: { required: ["followups"], properties: { followups: { type: "array", items: { type: "string" } } } },
    label: "critic"
  });
  const followups = critic !== null && !critic.error_kind && Array.isArray(critic.data.followups) ? critic.data.followups : [];
  const patched = followups.length ? await host.parallel(followups.slice(0, 8).map((f) => ({ input: `Investigate for project deep dive: ${String(f).slice(0, 2000)}` }))) : [];
  const allRefs = [...sweeps.map((s) => s.ref), critic.ref, ...patched.map((p) => p.ref)].slice(0, 8);
  const synthesis = await host.agent({
    input: `Write the final project deep-dive onboarding report from these refs: ${allRefs.join(" ")}. Cover: repo purpose, tech stack, directory map, FCM vs DataIntegration vs shared layers, architecture and conventions, build/test/lint gates, key entry points, and where to look next. Concise but complete.`,
    label: "synthesis"
  });
  return { status: "ok", ref: synthesis.ref, text: synthesis.text };
}"}

