7|/**
8| * Stellt ein Menue im FCM dar, welches weitere Untermenues oder Module enthalten kann.
9| * Bei dem Hinzufuegen neuer Module/Menues wird immer der Klassenname angegeben und nicht das
10| * Objekt selbst. Die Objekte werden bei Bedarf automatisch erzeugt. Die Zuordnung zu
11| * Subv-Klassen (Spezialisierungen fuer Partner) erfolgt automatisch ueber die Definition
12| * in der Datenbank. Die Funktion load_Module laedt automatisch die passende Klasse.
13| *
14| * @package   FCM\Frontend_Template
15| *
16| * @author    Janis Jekabsons <jj@fcm-eu.com>
17| * @author    Natalia Wildner
18| *
19| * @copyright 2011 - 2018 FCM GmbH
20| * @version   1.0.3
21| *
22| * @since     1.0.3 FCM-7113 replace error message 'cannot resolve route...' to redirect to access denied (JJ 2018-10-12)
23| * @since     1.0.2 FCM-6652 User permission for each administration module (NW 2018-07-23)
24| * @since     1.0.1 remove superfluous DebugNotifier (JJ 2018-03-12)
25| */
26|abstract class Menu extends Module_Link
27|{
28|    private array $links;
29|    /**
30|     * @deprecated
31|     * @var array $cache
32|     */
33|    protected $cache;
34|    /** @var int Aktuell ausgewaehlter Menuepunkt (Modul) */
35|    protected $actModule;
36|    /** @var object Hilfsobject fuer Cache Verwaltung */
37|    protected $htmlHelper;
38|    /** @var array $topLockLevel Level Nummer fuer das Untermenü, dass gesperrt werden soll */
39|    protected $topLockLevel;
40|    /** @var array $modules */
41|    protected $modules;
42|
43|    /**
44|     * Menu constructor.
45|     *
46|     * @param object|bool $mainContent Content Bereich des FCM
47|     */
48|    public function __construct(protected $mainContent = false)
49|    {
50|        global $html_helper;
51|        parent::__construct();
52|        $this->htmlHelper   = $html_helper;
53|        $this->links        = [];
54|        $this->cache        = &$this->htmlHelper->generate_new_Cache(FCM_Setting::$MODULE_CACHE);
55|        $this->topLockLevel = [];
56|        $this->modules      = [];
57|        $this->set_Submenu_Invisible();
58|    }
59|
60|    /**
61|     * Ermittelt das aktuelle ausgewaehlte Modul dieses Menues und speichert es im Cache.
62|     * Die Variable $this->act_module wird mit dem ermittelten Wert belegt.
63|     *
64|     * @throws \Exception
65|     */
66|    protected function get_ActModule(): void
67|    {
68|        $superGlobals = SuperGlobals::getInstance();
69|        /** @var \User $user */
70|        $user = $superGlobals->getGlobalValue(SuperGlobals::USER);
71|        $menuCode        = $this->get_MenuCode();
72|        $this->actModule = &$this->htmlHelper->get_CacheParameter($this->cache, static::class, key($this->links));
73|        if (in_array($menuCode, ['a1', 'a2'])) {
74|            $actModule = (int)$this->htmlHelper->check_GETParameter($menuCode);
75|        } else {
76|            $actModule = $this->htmlHelper->check_GETParameter($menuCode);
77|        }
78|        if (! empty($actModule)) {
79|            if (isset($this->links[(int)$actModule])) {
80|                $this->actModule = $actModule;
81|            } elseif ($user->logged_In()) {
82|                /** @var \url $mainurl */
83|                $mainurl = $superGlobals->getGlobalValue(SuperGlobals::MAIN_URL);
84|                $mainurl->addParameter(DiUrl::A1, FCM_Setting::$TOPMENU_ACCESS_MODULE_DENIED);
85|                $mainurl->addParameter(DiUrl::A2, FCM_Setting::$SUBMODULE_ACCESS_DENIED);
86|                DiUrl::goToUrl($mainurl);
87|            }
88|        }
89|    }
90|
91|    /**
92|     * Gibt den Menue code des Menues zurueck, z.B. a1 anhand der Menuetiefe
93|     *
94|     * @return string Menue code dieses Menues.
95|     */
96|    protected function get_MenuCode(): string
97|    {
98|        // Menuetag +  Modultiefe , z.Bsp A1
99|        return Module_Link::$MENU_TAG . $this->get_Level();
100|    }
101|
102|    /**
103|     * Fuegt einen neuen Link zu dem Menue hinzu. Dieser Kann zu einem neuen Untermenue oder
104|     * Content fuehren.
105|     *
106|     * @param int    $number     Nummer des neuen Moduls
107|     * @param string $link       Module oder Menu Objekt
108|     * @param string $text       Anzeigetext fuer das Menue
109|     * @param bool   $visibility Sichtbarkeit des Menue/Moduls True=Sichtbar, false=unsichtbar
110|     * @param bool   $params
111|     * @param bool   $isImage
112|     */
113|    private function addLink($number, $link, $text, $visibility = true, $params = false, $isImage = false): void
114|    {
115|        $this->links[$number] = [$link, $text, $visibility, $params, $isImage];
116|    }
117|
118|    /**
119|     * Fuegt einen neuen Link zu dem Menue hinzu. Dieser Kann zu einem neuen Untermenue oder
120|     * Content fuehren.
121|     *
122|     * @param int           $number     Nummer des neuen Moduls
123|     * @param string|object $link       Module oder Menu Objekt
124|     * @param string        $text       Anzeigetext fuer das Menue
125|     * @param bool          $visibility Sichtbarkeit des Menue/Moduls True=Sichtbar, false=unsichtbar
126|     * @param bool          $params
127|     * @param bool          $isImage
128|     *
129|     * @throws \Exception
130|     *
131|     * @return bool|object|string
132|     */
133|    protected function generate_Link($number, $link, $text, $visibility = true, $params = false, $isImage = false)
134|    {
135|        if (! is_object($link)) {
136|            if (! $visibility && (int)$number !== (int)$this->actModule) {
137|                return '';
138|            }
139|            // Menuename kopieren
140|            $menuName = $link;
141|            // Menue erzeugen
142|            $link = Functions::load_Module($link);
143|            // Menuename nicht gefunden
144|            if (! $link) {
145|                ErrorHandler::trigger('Klasse: ' . self::class . ', Funktion: ' . __FUNCTION__ . ". Menue '" . $menuName . "' nicht gefunden!");
146|            }
147|        }
148|        if ($isImage) {
149|            // Wert der sich in dem Link befindet
150|            $link->set_Value($isImage);
151|        } else {
152|            // Wert der sich in dem Link befindet
153|            $link->set_Value($text);
154|        }
155|        // Sichtbarkeit setzen
156|        $link->set_Visibility($visibility);
157|        if (false !== $params) {
158|            $link->set_Params($params);
159|        }
160|
161|        return $link;
162|    }
163|
164|    /**
165|     * Fuegt ein neues Modul zu einem Menue Hinzu. Hier darf nicht das Objekt selbst uebergeben
166|     * werden, sondern nur der Klassenname! Dieses Modul fuellt den Maincontent des FCM, z.B;
167|     * Auftrag anlegen.
168|     *
169|     * @param int    $number     Nummer des neuen Moduls
170|     * @param string $content    Modulname (Klassenname) des zu erzeugenden Moduls
171|     * @param string $text       Anzeigetext fuer das Modul im Menue
172|     * @param bool   $visibility Sichtbarkeit des Moduls im Menue True=Sichtbar, false=unsichtbar
173|     * @param bool   $style
174|     * @param bool   $params
175|     * @param bool   $isImage
176|     */
177|    public function add_Module($number, $content, $text, $visibility = true, $style = false, $params = false, $isImage = false): void
178|    {
179|        global $user;
180|        // Neuen Modul-Link erzeugen.
181|        $module = new Module();
182|        $module->set_Module($content);
183|        $module->set_Module_Name($text);
184|        $module->link_container->setStyle($style);
185|        # Rechte abfrage
186|        $module_rights = $user->get_Right_Of_Module($content);
187|        # Prüfung ob ?berhaupt Eintr?ge in diesem Modul existieren
188|        if ($module_rights === false) {
189|            $module->set_Module('Denied');
190|        }
191|        // Auf diesem Menue Adden.
192|        $this->addLink($number, $module, $text, $visibility, $params, $isImage);
193|        // If the link is a home, store it into the custom home screens array
194|        Module_Logic::storeCustomHomeScreen($content, $number);
195|    }
196|
197|    /**
198|     * Fuegt ein neues Untermenue zu einem Menue Hinzu. Hier darf nicht das Objekt selbst
199|     * uebergeben, werden, sondern nur der Klassenname! Das neue Untermenue wird unter das
200|     * aktuelle als Submenue gesetzt und enthaelt die weiteren Submodule/Menues.
201|     *
202|     * @param int    $number     Nummer des neuen Menues
203|     * @param string $menu       Klassenname des Submenues
204|     * @param string $text       Anzeigetext fuer das Menue
205|     * @param bool   $visibility Sichtbarkeit des Menues True=Sichtbar, false=unsichtbar
206|     * @param bool   $params
207|     */
208|    public function add_Menu($number, $menu, $text, $visibility = true, $params = false): void
209|    {
210|        if (Functions::get_Right_Of_Module($menu) === false) {
211|            return;
212|        }
213|        # Auf diesem Menue Adden.
214|        $this->addLink($number, $menu, $text, $visibility, $params, false);
215|    }
216|
217|    /**
218|     * Fuegt die Menues und den Content auf den FCM.
219|     *
220|     * @throws \Exception
221|     */
222|    public function buildContent()
223|    {
224|        // Falls das Menue leer ist
225|        if (count($this->links) === 0) {
226|            ErrorHandler::trigger('Klasse: ' . self::class . ', Funktion: ' . __FUNCTION__ . ". Das Menue '" . $this->value . "' hat keine Untermodule!");
227|        }
228|        // Aktuelles Modul ermitteln.
229|        $this->get_ActModule();
230|        $actModule = false;
231|        // Module durchlaufen und Links
232|        foreach ($this->links as $number => $parameters) {
233|            // Aktuelle Menuenummern a1 - an
234|            $levels = $this->get_Levels();
235|            // Menuenummer einfuegen
236|            $levels[] = $number;
237|            $link     = $this->generate_Link($number, $parameters[0], $parameters[1], $parameters[2], $parameters[3], $parameters[4]);
238|            if ($link) {
239|                // Levels setzen
240|                $link->set_Levels($levels);
241|                // Modul ist aktuelles Modul
242|                if ((int)$number === (int)$this->actModule) {
243|                    // Aktuelles Modul hervorheben
244|                    $link->set_Highlighted(true);
245|                }
246|                // Link auf Menue setzen
247|                $this->add($link->get_Link($this->class_highlighted, $this->class_nothighlighted));
248|                if ((int)$number === (int)$this->actModule) {
249|                    $actModule = $link;
250|                }
251|            }
252|        }
253|        // Menue auf Content laden
254|        #$this->mainContent->add($this->buildElement());
255|        // Maincontent
256|        $actModule->set_MainContent($this->mainContent);
257|        // Untermenue/Modul auf Content laden
258|        $actModule->buildContent();
259|    }
260|
261|    /**
262|     * Weist den Platzhalter fuer den Maincontent zu
263|     *
264|     * @param object $content Platzhalter fuer den Maincontent
265|     */
266|    public function set_MainContent($content): void
267|    {
268|        $this->mainContent = $content;
269|    }
270|
271|    /**
272|     * Setzt ein Submeu unsichtbar
273|     */
274|    public function set_Submenu_Invisible(): void
275|    {
276|        $this->set_Style('display:none');
277|    }
278|
279|    /**
280|     * Function generate_Submenu
281|     *
282|     * @param int  $topMenuId
283|     * @param bool $invisible
284|     */
285|    public function generate_Submenu($topMenuId, $invisible = false): void
286|    {
287|        // Invisible Flag gesetzt?
288|        if ($invisible) {
289|            // Submenu invisible setzen
290|            $this->set_Submenu_Invisible();
291|        }
292|        // Alle Submenus holen
293|        $subMenus = $this->module_logic->get_All_Submenus_For_Topmenu($topMenuId);
294|        if (! empty($subMenus)) {
295|            // Durchlaufe alle Submenus
296|            foreach ($subMenus as $submenu) {
297|                // Submodules adden
298|                $this->add_Module(
299|                    $submenu['Module_Number'],
300|                    $submenu['Class_Name'],
301|                    $this->translate($submenu['Translation_Code']),
302|                    $submenu['Visible']
303|                );
304|            }
305|        }
306|    }
307|
308|    /**
309|     * Function getLinks
310|     *
311|     * @return array
312|     */
313|    public function getLinks(): array
314|    {
315|        return $this->links;
316|    }
