namespace FCM\Frontend;

use FCM\Frontend_Template\Card;
use FCM\Logic\BreadcrumbLogic;
use FCM_ActionForm;
use Functions;

/**
 * Blank Fleet View module, visible only for Renault France.
 *
 * @package   FCM\Frontend
 * @author    FCM <info@fcm-eu.com>
 * @copyright Fleet Control Monitor GmbH
 * @version   1.0.0
 * @since     1.0.0 Fleet View blank module (pid 3173 only)
 */
class FleetView extends FCM_ActionForm
{
    private const int PARTNER_RENAULT_FRANCE = 3173;

    public function __construct($name = false, $method = false, $action = false)
    {
        parent::__construct($name, $method, $action);
        $this->perform_Actions();
    }

    /**
     * @inheritDoc
     */
    public function buildForm(): void
    {
        parent::buildForm();
        BreadcrumbLogic::push($this->translate('fleetView'));
        $card = new Card();
        $card->setHeader($this->translate('fleetView'));
        $card->setContent($this->translate('fleetView'));
        $this->add($card->buildElement());
    }

    /**
     * Cockpit visibility gate for Renault France only.
     *
     * @return bool
     */
    public static function isFeatureAvailable(): bool
    {
        return Functions::getPartnerId() === self::PARTNER_RENAULT_FRANCE;
    }
}
